using System.ComponentModel.DataAnnotations;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Description { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public ShipmentStatus Status { get; set; }

    public DateTime? EstimatedDelivery { get; set; }

    [MaxLength(254)]
    public string CustomerEmail { get; set; } = string.Empty;

    public DateTime CreatedAt { get; set; }
    public DateTime? UpdatedAt { get; set; }

    public ShipmentDto ToDto() => new()
    {
        Id = Id,
        TrackingNumber = TrackingNumber,
        Description = Description,
        Origin = Origin,
        Destination = Destination,
        Status = Status,
        EstimatedDelivery = EstimatedDelivery,
        CustomerEmail = CustomerEmail,
        CreatedAt = CreatedAt,
        UpdatedAt = UpdatedAt
    };
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => s.ToDto())
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment?.ToDto();
    }

    public async Task<ShipmentDto> CreateShipmentAsync(CreateShipmentRequest request)
    {
        var shipment = new Shipment
        {
            TrackingNumber = GenerateTrackingNumber(),
            Description = request.Description,
            Origin = request.Origin,
            Destination = request.Destination,
            CustomerEmail = request.CustomerEmail,
            EstimatedDelivery = request.EstimatedDelivery,
            Status = ShipmentStatus.Pending,
            CreatedAt = DateTime.UtcNow
        };

        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return shipment.ToDto();
    }

    public async Task<ShipmentDto?> UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is null) return null;

        shipment.Status = newStatus;
        shipment.UpdatedAt = DateTime.UtcNow;
        await db.SaveChangesAsync();
        return shipment.ToDto();
    }

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";
    }
}

