// Ensure database is created and seeded
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    db.Database.Migrate();

    if (!db.Shipments.Any())
    {
        db.Shipments.AddRange(
            new Shipment
            {
                TrackingNumber = "SHP-20260615-100001",
                Description = "Electronics - Laptop",
                Origin = "Los Angeles, CA",
                Destination = "New York, NY",
                Status = ShipmentStatus.InTransit,
                CustomerEmail = "customer1@example.com",
                EstimatedDelivery = DateTime.UtcNow.AddDays(3),
                CreatedAt = DateTime.UtcNow.AddDays(-2)
            },
            new Shipment
            {
                TrackingNumber = "SHP-20260615-100002",
                Description = "Furniture - Office Desk",
                Origin = "Chicago, IL",
                Destination = "Miami, FL",
                Status = ShipmentStatus.Pending,
                CustomerEmail = "customer2@example.com",
                EstimatedDelivery = DateTime.UtcNow.AddDays(7),
                CreatedAt = DateTime.UtcNow.AddDays(-1)
            },
            new Shipment
            {
                TrackingNumber = "SHP-20260615-100003",
                Description = "Medical Supplies",
                Origin = "Seattle, WA",
                Destination = "Denver, CO",
                Status = ShipmentStatus.Delivered,
                CustomerEmail = "customer3@example.com",
                EstimatedDelivery = DateTime.UtcNow.AddDays(-1),
                CreatedAt = DateTime.UtcNow.AddDays(-5),
                UpdatedAt = DateTime.UtcNow.AddDays(-1)
            },
            new Shipment
            {
                TrackingNumber = "SHP-20260615-100004",
                Description = "Auto Parts - Engine Components",
                Origin = "Detroit, MI",
                Destination = "Houston, TX",
                Status = ShipmentStatus.OutForDelivery,
                CustomerEmail = "customer4@example.com",
                EstimatedDelivery = DateTime.UtcNow,
                CreatedAt = DateTime.UtcNow.AddDays(-3)
            }
        );
        db.SaveChanges();
    }
}

// Shipment API endpoints
