{
    var shipment = await service.GetByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).RequireAuthorization();

shipments.MapPost("/", async (CreateShipmentRequest request, IShipmentService service) =>
{
    var shipment = await service.CreateShipmentAsync(request);
    return Results.Created($"api/shipments/track/{shipment.TrackingNumber}", shipment);
}).RequireAuthorization();

shipments.MapPut("/{id}/status", async (int id, StatusUpdateRequest request, IShipmentService service) =>
{
    var shipment = await service.UpdateStatusAsync(id, request.Status);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).RequireAuthorization();

// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

