@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<div class="text-center py-4">
    <h1>Shipment Tracker</h1>
    <p class="lead">Track your shipments in real time.</p>
</div>

<div class="row justify-content-center">
    <div class="col-md-6">
        <div class="card shadow-sm">
            <div class="card-body">
                <h5 class="card-title">Track a Shipment</h5>
                <div class="input-group">
                    <input type="text" class="form-control" placeholder="Enter tracking number (e.g. SHP-20260615-100001)"
                           @bind="trackingNumber" @bind:event="oninput"
                           @onkeydown="HandleKeyDown" />
                    <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                        Track
                    </button>
                </div>
            </div>
        </div>
    </div>
</div>

<AuthorizeView>
    <Authorized>
        <div class="row mt-4 justify-content-center">
            <div class="col-md-6 text-center">
                <a href="shipments" class="btn btn-outline-primary">Go to Dispatcher Dashboard</a>
            </div>
        </div>
    </Authorized>
    <NotAuthorized>
        <div class="row mt-4 justify-content-center">
            <div class="col-md-6 text-center text-muted">
                <a href="Account/Login">Log in</a> to access the dispatcher dashboard.
            </div>
        </div>
    </NotAuthorized>
</AuthorizeView>

@code {
    [Inject] private NavigationManager Nav { get; set; } = default!;

    private string trackingNumber = "";

    private void TrackShipment()
    {
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            Nav.NavigateTo($"track/{Uri.EscapeDataString(trackingNumber.Trim())}");
        }
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") TrackShipment();
    }
}

arguments.file_text:
@page "/track/{TrackingNumber}"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

<PageTitle>Track Shipment</PageTitle>

<h2>Shipment Tracking</h2>

@if (loading)
{
    <p><em>Looking up shipment...</em></p>
}
else if (shipment is null)
{
    <div class="alert alert-warning">
        No shipment found for tracking number <strong>@TrackingNumber</strong>.
        <br />
        <a href="/">Try another tracking number</a>
    </div>
}
else
{
    <div class="card shadow-sm">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@shipment.TrackingNumber</strong>
            <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row mb-3">
                <div class="col-md-6">
                    <strong>Description:</strong>
                    <p>@shipment.Description</p>
                </div>
                <div class="col-md-6">
                    <strong>Customer:</strong>
                    <p>@shipment.CustomerEmail</p>
                </div>
            </div>
            <div class="row mb-3">
                <div class="col-md-6">
                    <strong>Origin:</strong>
                    <p>@shipment.Origin</p>
                </div>
                <div class="col-md-6">
                    <strong>Destination:</strong>
                    <p>@shipment.Destination</p>
                </div>
            </div>
            <div class="row">
                <div class="col-md-6">
                    <strong>Created:</strong>
                    <p>@shipment.CreatedAt.ToString("MMM dd, yyyy HH:mm") UTC</p>
                </div>
                <div class="col-md-6">
                    <strong>Estimated Delivery:</strong>
                    <p>@(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")</p>
                </div>
            </div>
        </div>
    </div>

    <div class="mt-3">
        <a href="/" class="btn btn-outline-secondary">Track Another Shipment</a>
    </div>
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = "";
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private ShipmentDto? shipment;
    private bool loading = true;

    protected override async Task OnParametersSetAsync()
    {
        loading = true;
        shipment = await ShipmentService.GetByTrackingNumberAsync(TrackingNumber);
        loading = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-primary",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>Dispatcher Dashboard</h2>

<div class="d-flex justify-content-between align-items-center mb-3">
    <div class="input-group" style="max-width: 350px;">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="filterText" @bind:event="oninput" />
        @if (!string.IsNullOrEmpty(filterText))
        {
            <button class="btn btn-outline-secondary" @onclick="() => filterText = string.Empty">Clear</button>
        }
    </div>
    <button class="btn btn-primary" @onclick="() => showCreateForm = !showCreateForm">
        @(showCreateForm ? "Cancel" : "+ New Shipment")
    </button>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Description</label>
                    <input class="form-control" @bind="newShipment.Description" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Customer Email</label>
                    <input type="email" class="form-control" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Origin</label>
                    <input class="form-control" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Destination</label>
                    <input class="form-control" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Estimated Delivery</label>
                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-12">
                    <button class="btn btn-success" @onclick="CreateShipment" disabled="@creating">
                        @(creating ? "Creating..." : "Create Shipment")
                    </button>
                </div>
            </div>
            @if (!string.IsNullOrEmpty(createError))
            {
                <div class="alert alert-danger mt-2">@createError</div>
            }
        </div>
    </div>
}

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments is null || shipments.Count == 0)
{
